-- Bản live cũ chỉ có đơn gốc; clone rớt này là bản thừa làm số liệu ngày 27/08 bị tách đôi.
update public.khsx_orders set deleted_at=coalesce(deleted_at,now()),
  cancel_reason='Đối chiếu chính xác live cũ v83 trong v124',cancelled_by=null,updated_at=now()
where id='s_bccb3d6aab99295021b5f7eb5b35b43c';

-- Tổ phụ trách phải đúng theo live cũ cho toàn bộ đơn trong phạm vi.
insert into public.khsx_order_assignments(order_id,plan_team,current_team,change_note)
select e.id,replace(e.team,'Tổ','To')::public.khsx_unit,replace(e.team,'Tổ','To')::public.khsx_unit,
       'Đối chiếu chính xác live cũ v83 trong v124'
from _v124_expected_order e where e.team is not null
on conflict(order_id) do update set plan_team=excluded.plan_team,current_team=excluded.current_team,
  change_note=excluded.change_note,updated_at=now();

-- Xóa đúng các dòng tiến độ không tồn tại trong live cũ rồi nạp lại toàn bộ 301 dòng nguồn.
delete from public.khsx_stage_credits c
where c.work_date between date '2026-08-25' and date '2026-08-29';

delete from public.khsx_stage_progress p
where p.work_date between date '2026-08-25' and date '2026-08-29';

insert into public.khsx_stage_progress(order_id,work_date,stage,quantity,kpi_team,entered_by,completed_by_worker_id)
select e.order_id,e.work_date,e.stage::public.khsx_stage,e.quantity,
       replace(e.team,'Tổ','To')::public.khsx_unit,null,
       case e.worker_code when 'loananh' then 'loan_anh' when 'baocham' then 'bao_cham'
         when 'thaovy' then 'thao_vy' when 'minhthuan' then 'minh_thuan' else null end
from _v124_expected_progress e
on conflict(order_id,work_date,stage) do update set quantity=excluded.quantity,kpi_team=excluded.kpi_team,
  entered_by=null,completed_by_worker_id=excluded.completed_by_worker_id,updated_at=now();

insert into public.khsx_stage_credits(order_id,work_date,stage,worker_id,quantity,source)
select e.order_id,e.work_date,e.stage::public.khsx_stage,
       case e.worker_code when 'loananh' then 'loan_anh' when 'baocham' then 'bao_cham'
         when 'thaovy' then 'thao_vy' when 'minhthuan' then 'minh_thuan' end,
       e.quantity,'old_live_v83_exact_v124'
from _v124_expected_progress e where e.worker_code is not null
on conflict(order_id,work_date,stage,worker_id) do update set quantity=excluded.quantity,
  source=excluded.source,updated_at=now();

delete from public.khsx_daily_assignments a
where a.work_date between date '2026-08-25' and date '2026-08-29' and a.assignment_kind='support';

insert into public.khsx_daily_assignments(order_id,work_date,team_name,assignment_kind,assigned_by,updated_at)
select e.order_id,e.work_date,replace(e.team,'Tổ','To')::public.khsx_unit,'support',null,now()
from _v124_expected_support e
on conflict(order_id,work_date,assignment_kind) do update set team_name=excluded.team_name,assigned_by=null,updated_at=now();

update public.khsx_orders o set source_payload=jsonb_set(coalesce(o.source_payload,'{}'::jsonb),'{reconciliation_v124}',
  jsonb_build_object('source','old_live_v83_exact','range','2026-08-25..2026-08-29','verified_at',now()),true),updated_at=now()
where o.id in (select id from _v124_expected_order)
   or o.id='s_bccb3d6aab99295021b5f7eb5b35b43c';

do $$
declare bad text;
begin
  if (select count(*) from _v124_expected_order)<>100 then raise exception 'Nguồn v124 không đủ 100 dòng đơn'; end if;
  if (select count(*) from _v124_expected_progress)<>301 then raise exception 'Nguồn v124 không đủ 301 dòng tiến độ'; end if;
  if (select count(*) from _v124_expected_support)<>1 then raise exception 'Nguồn v124 không đúng 1 dòng tổ hỗ trợ'; end if;

  select string_agg(e.id,', ') into bad
  from _v124_expected_order e left join public.khsx_orders o on o.id=e.id and o.deleted_at is null
  left join public.khsx_order_assignments a on a.order_id=e.id
  where o.id is null or coalesce(o.product_code,'')<>coalesce(e.product_code,'')
     or coalesce(o.product_name,'')<>coalesce(e.product_name,'') or coalesce(o.plan_qty,0)<>coalesce(e.plan_qty,0)
     or o.is_manual<>e.is_manual or o.is_drop<>e.is_drop or o.is_ghost<>e.is_ghost or o.is_warranty<>e.is_warranty
     or (e.team is not null and replace(e.team,'Tổ','To')<>a.current_team::text);
  if bad is not null then raise exception 'Đơn KHSX chưa khớp live cũ: %',bad; end if;

  if exists(select 1 from public.khsx_orders o where o.deleted_at is null
    and o.production_date between date '2026-08-25' and date '2026-08-29'
    and not exists(select 1 from _v124_expected_order e where e.id=o.id))
  then raise exception 'Supabase còn đơn thừa so với live cũ'; end if;

  with actual as (
    select p.order_id,p.work_date,p.stage::text stage,sum(p.quantity)::numeric quantity,max(p.kpi_team::text) team,
      max(p.completed_by_worker_id) worker
    from public.khsx_stage_progress p where p.work_date between date '2026-08-25' and date '2026-08-29'
    group by p.order_id,p.work_date,p.stage
  ), diff as (
    select coalesce(e.order_id,a.order_id) id from _v124_expected_progress e full join actual a
      on a.order_id=e.order_id and a.work_date=e.work_date and a.stage=e.stage
    where e.order_id is null or a.order_id is null or e.quantity<>a.quantity
      or replace(e.team,'Tổ','To')<>a.team
      or (e.worker_code is not null and
        case e.worker_code when 'loananh' then 'loan_anh' when 'baocham' then 'bao_cham'
          when 'thaovy' then 'thao_vy' when 'minhthuan' then 'minh_thuan' end<>a.worker)
  ) select string_agg(id,', ') into bad from diff;
  if bad is not null then raise exception 'Tiến độ chưa khớp live cũ: %',bad; end if;

  if (select count(*) from public.khsx_stage_credits where work_date between date '2026-08-25' and date '2026-08-29')<>202
  then raise exception 'Số dòng ghi nhận nhân viên không đúng 202'; end if;

  if (select count(*) from public.khsx_daily_assignments where work_date between date '2026-08-25' and date '2026-08-29' and assignment_kind='support')<>1
  then raise exception 'Tổ hỗ trợ không đúng live cũ'; end if;

  if (select coalesce(sum(plan_qty),0) from public.khsx_orders where deleted_at is null and is_warranty
      and production_date between date '2026-08-01' and date '2026-08-31')<>122
  then raise exception 'Bảo hành tháng 8 chưa đạt 122'; end if;
end $$;

commit;
